# Let me check connected components of 1s in the demo
# And see if 1s that are part of certain connected components trigger 8s

def get_connected_components(grid, min_size=2):
    rows = len(grid)
    cols = len(grid[0])
    visited = [[False]*cols for _ in range(rows)]
    components = []

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1 and not visited[r][c]:
                comp = []
                stack = [(r, c)]
                visited[r][c] = True
                while stack:
                    cur_r, cur_c = stack.pop()
                    comp.append((cur_r, cur_c))
                    for dr, dc in [(0,1), (0,-1), (1,0), (-1,0)]:
                        nr, nc = cur_r + dr, cur_c + dc
                        if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == 1 and not visited[nr][nc]:
                            visited[nr][nc] = True
                            stack.append((nr, nc))
                if len(comp) >= min_size:
                    components.append(comp)
    return components

